def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    parent = [-1] * n
    order = []
    if n:
        parent[0] = 0
        stack = [0]
        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if parent[v] == -1:
                    parent[v] = u
                    stack.append(v)

    subtree = [0] * n
    for u in reversed(order):
        subtree[u] = w[u]
        for v in adj[u]:
            if parent[v] == u:
                subtree[u] += subtree[v]

    depth = [0] * n
    for u in order:
        if u:
            depth[u] = depth[parent[u]] + 1

    ans = [0] * n
    if n:
        ans[0] = sum(w[u] * depth[u] for u in range(n))
        total = subtree[0]
        for u in order:
            if u:
                ans[u] = ans[parent[u]] + total - 2 * subtree[u]
    return ans
